// Never Start Over (The AI Business Starter System) for thenailbawse.com, served by the thenailbawse-official Worker.
// Built by operations/never-start-over/build_shop.py from shop.body.html + shop.css. Do not edit shop.js by hand.
// Routes:
//   /shop                      sales page; the price shown follows the Pacific date (no promo code is ever printed)
//   /shop/buy                  sends the buyer to the right Stripe Payment Link for today's Pacific date
//   /never-start-over/<token>  the private product (HTML kept in the NSO_KV namespace, never in this public repo)
// Worker settings this module reads (Cloudflare dashboard > Worker > Settings > Variables and bindings):
//   NSO_TOKEN      the private access path segment          NSO_KV       KV namespace holding "hub.html"
//   NSO_LINK_BF    Stripe Payment Link for the $97 price    NSO_LINK_FULL Stripe Payment Link for $197 (promotion codes on)
const BODY = "<div class=\"nso\">\n\n<section class=\"nso-hero\">\n  <div class=\"nso-wrap\">\n    <p class=\"nso-eyebrow\">The AI Business Starter System · by The Nail Bawse™</p>\n    <h1 class=\"nso-display\">Never Start <em>Over.</em></h1>\n    <p class=\"nso-tagline\">Life will pull you out of the chair. Your business shouldn't disappear when it does.</p>\n    <p class=\"nso-lead\">Use AI to actually run your business, not just collect prompts. Made for nail techs and beauty pros who are new to AI, or done getting generic answers from it.</p>\n    {{PRICE}}\n  </div>\n</section>\n\n<section class=\"nso-sec nso-dark\">\n  <div class=\"nso-wrap\">\n    <p class=\"nso-eyebrow light\">Where it hurts</p>\n    <h2 class=\"nso-h2\">Be honest. What did your business cost you <em>this week?</em></h2>\n    <ul class=\"nso-hurts\">\n      <li>You answered DMs at the dinner table.</li>\n      <li>You missed homework time because the chair was booked till 8.</li>\n      <li>Your kids heard \"after this client\" more than they heard \"yes.\"</li>\n      <li>You answered an 11 PM text like it was an emergency.</li>\n      <li>You haven't had a real day off without your phone in your hand.</li>\n    </ul>\n    <p class=\"nso-p\">Here's what nobody tells you. When you ARE the whole business, the business stops the second you stop. And life will make you stop. Sickness. Family. Grief. Kids. It's not if. It's when.</p>\n  </div>\n</section>\n\n<section class=\"nso-sec\">\n  <div class=\"nso-wrap nso-story\">\n    <img class=\"nso-photo\" src=\"https://static.wixstatic.com/media/86a5ad_65777c887ac14c5d9884accaf44a6826~mv2.jpg\" alt=\"Anisia Burroughs, The Nail Bawse\" loading=\"lazy\" width=\"600\" height=\"750\">\n    <div>\n      <p class=\"nso-eyebrow\">Why I built this</p>\n      <h2 class=\"nso-h2\">I lost my whole book of <em>200+ clients.</em></h2>\n      <p class=\"nso-p\">I had a full book. Over 200 clients. Then my mom went on hospice, and I had to drop everything to be with her.</p>\n      <p class=\"nso-p\">Two weeks later, she was gone. When I came back to my business, there was nothing left to come back to. No clients. No money. Nothing had kept running while I was gone, because everything ran through me.</p>\n      <p class=\"nso-p\">I rebuilt from zero. Now my mission is to help you build a business that holds the value of your skill and your knowledge, even on the days you can't be in the chair.</p>\n      <p class=\"nso-p\"><b>Never Start Over is the system I wish I'd had.</b></p>\n      <p class=\"nso-sig\">— Anisia Burroughs, The Nail Bawse</p>\n    </div>\n  </div>\n</section>\n\n<section class=\"nso-sec nso-cream\">\n  <div class=\"nso-wrap\">\n    <p class=\"nso-eyebrow\">The industry changed. Did your business?</p>\n    <h2 class=\"nso-h2\">More money is moving through nails than ever. <em>Most of it runs through your two hands.</em></h2>\n    <p class=\"nso-p\">I've watched this industry change more in the last six years than it did in the twenty years before. The numbers show it:</p>\n    <div class=\"nso-stats\">\n      <div class=\"nso-stat\"><b>$5.84B → $13.08B</b><span>What U.S. nail salons with employees brought in, 2020 vs. 2024. More than double.</span><i>U.S. Census Bureau</i></div>\n      <div class=\"nso-stat\"><b>295,977</b><span>U.S. nail businesses with no employees in 2023. The solo tech, the suite, the home studio. One person, no backup.</span><i>U.S. Census Bureau, Nonemployer Statistics</i></div>\n      <div class=\"nso-stat\"><b>7%</b><span>Drop in new guest visits at specialty salons in 2025. New clients are harder to win, so keeping the ones you have matters more.</span><i>Zenoti 2026 Benchmark Report (salons on its platform)</i></div>\n      <div class=\"nso-stat\"><b>220,400</b><span>Manicurist and pedicurist jobs projected by 2035, up from about 201,800 in 2025. More techs. More competition.</span><i>U.S. Bureau of Labor Statistics</i></div>\n    </div>\n    <p class=\"nso-p\">The industry grew up. Booking, DMs, reminders, content, follow-ups: the front desk work grew right along with it. If you're a one-person business, all of that lands on you. <b>That's the part AI can carry.</b></p>\n    <p class=\"nso-src\">Figures as reported in Fleur De Spa's \"U.S. Nail Salon Industry Report 2026\" (Oct 2026), citing the U.S. Census Bureau, the Bureau of Labor Statistics and Zenoti.</p>\n  </div>\n</section>\n\n<section class=\"nso-sec\">\n  <div class=\"nso-wrap\">\n    <p class=\"nso-eyebrow\">What you're really buying</p>\n    <h2 class=\"nso-h2\">This isn't about AI. <em>It's about options.</em></h2>\n    <p class=\"nso-p\">The option to be at the homework table while your front desk answers DMs. To sit in the bleachers instead of your inbox. To sit at a bedside without watching your business disappear. To take a day off and come back to a full book.</p>\n    <p class=\"nso-p\">You can't buy time. You can't buy being there. But you can build a business that doesn't need you every single minute. <b>That's bigger than anything anyone can sell you, me included.</b> This system is how you start.</p>\n  </div>\n</section>\n\n<section class=\"nso-sec nso-cream\" id=\"inside\">\n  <div class=\"nso-wrap\">\n    <p class=\"nso-eyebrow\">What's inside</p>\n    <h2 class=\"nso-h2\">One system. <em>Three parts.</em> Built to work together.</h2>\n    <div class=\"nso-parts\">\n      <article class=\"nso-part sky\">\n        <span class=\"nso-num\">Part 1</span>\n        <h3>Talk to AI Like a Bawse</h3>\n        <p>30 ready-to-use prompts in 5 simple categories: <b>Answer &amp; Book, Keep Them Coming Back, Protect Your Time &amp; Money, Get Seen,</b> and <b>Run Your Life Too</b>. Plus 10 sentence starters for when the answer isn't quite right. No tech words. If you can text a client, you can use these, and they fill in with your own business info.</p>\n      </article>\n      <article class=\"nso-part blush\">\n        <span class=\"nso-num\">Part 2</span>\n        <h3>My Business Brain</h3>\n        <p>Your personal business dashboard. Your services, prices, policies, clients, offers, your voice, and the family time you protect. Fill it once and every prompt, and your AI Employee, knows your business. It saves on your phone, and you can download it anytime.</p>\n      </article>\n      <article class=\"nso-part lemon\">\n        <span class=\"nso-num\">Part 3</span>\n        <h3>Your First AI Employee</h3>\n        <p>Your <b>AI Front Desk Manager</b>, ready to switch on in ChatGPT or Claude in about 15 minutes. It drafts your DM replies, booking messages, reminders, no-show replies, rebooking texts and your \"life happened\" messages, in your voice, with your Business Brain already loaded in.</p>\n      </article>\n      <article class=\"nso-part\">\n        <span class=\"nso-num\">Plus</span>\n        <h3>Start Here</h3>\n        <p>A 3-step plan that tells you exactly what to do first, second and third, so you get your first win in one sitting.</p>\n      </article>\n    </div>\n  </div>\n</section>\n\n<section class=\"nso-sec\">\n  <div class=\"nso-wrap\">\n    <p class=\"nso-eyebrow\">Your First AI Employee</p>\n    <h2 class=\"nso-h2\">It takes the job that <em>eats your whole day.</em></h2>\n    <p class=\"nso-p\">The biggest bottleneck in a one-person beauty business is the front desk, and the front desk is you. Your Front Desk Manager handles:</p>\n    <ul class=\"nso-checks\">\n      <li><b>Every DM:</b> paste the message, get the reply.</li>\n      <li><b>Booking and deposits:</b> your link and your policy, every time.</li>\n      <li><b>No-shows:</b> confirmations, reminders, and firm, kind replies.</li>\n      <li><b>An empty chair:</b> rebooking texts, win-backs and open-spot posts.</li>\n      <li><b>Family time:</b> it never suggests the hours you've blocked.</li>\n      <li><b>Life happened:</b> reschedule everyone kindly, fast, and keep your privacy.</li>\n    </ul>\n    <p class=\"nso-small\">It writes. You send. You stay in control of every word that goes out under your name.</p>\n  </div>\n</section>\n\n<section class=\"nso-sec nso-cream\">\n  <div class=\"nso-wrap nso-two\">\n    <div class=\"nso-box yes\">\n      <h3>This is for you if…</h3>\n      <ul>\n        <li>You're a nail tech or beauty pro (lashes, hair, brows, skin) who runs the business yourself</li>\n        <li>You're new to AI, or you tried it and got generic junk</li>\n        <li>You're tired of being your own front desk</li>\n        <li>You want time with your people without losing your book</li>\n      </ul>\n    </div>\n    <div class=\"nso-box no\">\n      <h3>This is not for you if…</h3>\n      <ul>\n        <li>You want a pile of prompts to save and never use</li>\n        <li>You want someone else to run your business for you</li>\n        <li>You're looking for a get-rich-quick thing</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<section class=\"nso-sec\" id=\"price\">\n  <div class=\"nso-wrap nso-center\">\n    <p class=\"nso-eyebrow\">Get it today</p>\n    <h2 class=\"nso-h2\">Your business, <em>still standing</em> when life calls.</h2>\n    <ul class=\"nso-mini\">\n      <li>Talk to AI Like a Bawse: 30 prompts + 10 sentence starters</li>\n      <li>My Business Brain: your personal business dashboard</li>\n      <li>Your First AI Employee: AI Front Desk Manager setup for ChatGPT or Claude</li>\n      <li>Start Here: your 3-step plan to your first win</li>\n    </ul>\n    {{PRICE}}\n    <p class=\"nso-small\">You'll need a phone or laptop and a free or paid ChatGPT or Claude account.</p>\n  </div>\n</section>\n\n<section class=\"nso-sec nso-cream\">\n  <div class=\"nso-wrap\">\n    <p class=\"nso-eyebrow\">Questions</p>\n    <h2 class=\"nso-h2\">Real talk.</h2>\n    <details class=\"nso-faq\"><summary>I'm not techy. Can I really do this?</summary><p>Yes. It's written so a 3rd grader could follow it. If you can copy and paste, you can do this.</p></details>\n    <details class=\"nso-faq\"><summary>Which AI do I need?</summary><p>ChatGPT or Claude. A free account works with the copy-paste setup that's included. Building your own custom GPT needs a paid ChatGPT plan.</p></details>\n    <details class=\"nso-faq\"><summary>How do I get it?</summary><p>Right after checkout, you land on your private access page. The link comes to your email too. Save it to your phone's home screen and it opens like an app.</p></details>\n    <details class=\"nso-faq\"><summary>Is this a course?</summary><p>No videos to sit through. It's a working system you use on your phone, between clients.</p></details>\n    <details class=\"nso-faq\"><summary>I'm a lash artist or a stylist. Will it work for me?</summary><p>Yes. It was built for nail techs first, and it works for any beauty pro who runs on appointments.</p></details>\n    <details class=\"nso-faq\"><summary>Does the AI text my clients for me?</summary><p>No. It writes the messages and you send them. You stay the Bawse.</p></details>\n    <details class=\"nso-faq\"><summary>Is my business info private?</summary><p>Your Business Brain saves on your own phone or computer. The Nail Bawse never sees it.</p></details>\n    <details class=\"nso-faq\"><summary>More questions?</summary><p>DM me on Instagram at <a href=\"https://www.instagram.com/thenailbawse/\" target=\"_blank\" rel=\"noopener\">@thenailbawse</a>.</p></details>\n  </div>\n</section>\n\n<section class=\"nso-sec\">\n  <div class=\"nso-wrap\">\n    <p class=\"nso-eyebrow\">Want hands-on help?</p>\n    <article class=\"nso-session\">\n      <h3>1:1 Nail Business Strategy Session with Anisia</h3>\n      <p class=\"nso-amt-sm\">$250</p>\n      <p class=\"nso-p\">A private strategy session with Anisia, focused on your business.</p>\n      <a class=\"nso-btn ghost\" href=\"{{SESSION_URL}}\" target=\"_blank\" rel=\"noopener noreferrer\">Book your session →</a>\n    </article>\n  </div>\n</section>\n\n</div>\n";
const CSS = ".nso{--blush:#F6B7CC;--blush-soft:#FDE7EF;--lemon:#FFF3BF;--sky:#B9DDF4;--sky-soft:#E6F3FC;--white:#FFFFFF;--esp:#39261F;--muted:#6E5850;--line:#EADBD3;--rose:#B4466F;--serif:\"Playfair Display\",Georgia,\"Times New Roman\",serif;--sans:\"Inter\",system-ui,-apple-system,\"Segoe UI\",Arial,sans-serif;font-family:var(--sans);color:var(--esp);background:var(--white);overflow-x:clip}.nso *{box-sizing:border-box}.nso h1,.nso h2,.nso h3,.nso p,.nso ul{margin:0}.nso-wrap{max-width:820px;margin:0 auto;padding:0 16px}.nso-center{text-align:center}.nso-eyebrow{font:800 .72rem/1.4 var(--sans);letter-spacing:.18em;text-transform:uppercase;color:var(--rose);margin-bottom:10px}.nso-eyebrow.light{color:var(--blush)}.nso-display{font-family:var(--serif);font-weight:700;font-size:clamp(3rem,13vw,5.6rem);line-height:.98;letter-spacing:-.02em}.nso-display em,.nso-h2 em{font-style:italic;color:var(--rose)}.nso-dark .nso-h2 em{color:var(--blush)}.nso-h2{font-family:var(--serif);font-weight:700;font-size:clamp(1.8rem,6.6vw,2.6rem);line-height:1.1;letter-spacing:-.01em;margin-bottom:16px}.nso-tagline{font-family:var(--serif);font-style:italic;font-size:clamp(1.3rem,5vw,1.75rem);line-height:1.3;margin:18px 0 14px}.nso-lead{font-size:1.05rem;line-height:1.65;color:var(--muted);max-width:620px}.nso-p{font-size:1.02rem;line-height:1.7;margin:0 0 14px}.nso-small{font-size:.86rem;color:var(--muted);margin-top:10px}.nso-src{font-size:.75rem;color:var(--muted);margin-top:8px}.nso-hero{padding:48px 0 56px;background:radial-gradient(90% 70% at 100% 0%,var(--blush-soft),transparent 60%),radial-gradient(70% 60% at 0% 100%,var(--sky-soft),transparent 60%),var(--white)}.nso-sec{padding:56px 0}.nso-cream{background:#FFFBEA}.nso-dark{background:var(--esp);color:var(--white)}.nso-dark .nso-p{color:#F3E6E0}.nso-hurts{list-style:none;padding:0;margin:6px 0 22px;display:grid;gap:10px}.nso-hurts li{background:rgba(255,255,255,.07);border-left:4px solid var(--blush);border-radius:10px;padding:12px 14px;font-size:1.02rem;line-height:1.5}.nso-story{display:grid;gap:24px;align-items:start}.nso-photo{width:100%;max-width:360px;height:auto;border-radius:22px;box-shadow:0 18px 40px -22px rgba(57,38,31,.6);border:6px solid var(--blush)}.nso-sig{font-family:var(--serif);font-style:italic;font-size:1.2rem}.nso-stats{display:grid;gap:12px;margin:18px 0 22px}.nso-stat{background:var(--white);border:1px solid var(--line);border-radius:16px;padding:16px}.nso-stat b{display:block;font-family:var(--serif);font-size:1.7rem;line-height:1.1;margin-bottom:6px}.nso-stat span{display:block;font-size:.95rem;line-height:1.55}.nso-stat i{display:block;font-style:normal;font-size:.72rem;color:var(--muted);margin-top:8px;letter-spacing:.02em}.nso-parts{display:grid;gap:14px;margin-top:8px}.nso-part{background:var(--white);border:1px solid var(--line);border-radius:20px;padding:20px}.nso-part.sky{background:var(--sky-soft);border-color:#CDE5F5}.nso-part.blush{background:var(--blush-soft);border-color:#F4CADA}.nso-part.lemon{background:var(--lemon);border-color:#F0DE95}.nso-part h3{font-family:var(--serif);font-size:1.45rem;line-height:1.15;margin:6px 0 8px}.nso-part p{font-size:.98rem;line-height:1.65}.nso-num{display:inline-block;font-size:.68rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase;background:var(--esp);color:var(--white);border-radius:99px;padding:4px 10px}.nso-checks{list-style:none;padding:0;margin:8px 0 6px;display:grid;gap:10px}.nso-checks li{position:relative;padding-left:34px;font-size:1rem;line-height:1.55}.nso-checks li::before{content:\"✓\";position:absolute;left:0;top:0;width:24px;height:24px;border-radius:50%;background:var(--blush);display:grid;place-items:center;font-weight:800;font-size:.8rem}.nso-two{display:grid;gap:14px}.nso-box{border-radius:20px;padding:20px;border:1px solid var(--line);background:var(--white)}.nso-box.yes{border-top:6px solid var(--sky)}.nso-box.no{border-top:6px solid var(--blush)}.nso-box h3{font-family:var(--serif);font-size:1.3rem;margin-bottom:10px}.nso-box ul{padding-left:20px;display:grid;gap:8px;line-height:1.55}.nso-mini{list-style:none;padding:0;margin:0 auto 18px;max-width:520px;text-align:left;display:grid;gap:8px}.nso-mini li{background:var(--sky-soft);border-radius:12px;padding:10px 14px;font-weight:600;font-size:.95rem}.nso-price{margin:26px auto 0;max-width:460px;background:var(--white);border:2px solid var(--esp);border-radius:24px;padding:22px 20px;text-align:center;box-shadow:10px 10px 0 var(--blush)}.nso-tag{display:inline-block;background:var(--lemon);border-radius:99px;padding:5px 12px;font-size:.75rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.nso-amt{font-family:var(--serif);font-weight:700;font-size:3.4rem;line-height:1.1;margin:10px 0 14px}.nso-amt s{font-size:1.6rem;color:var(--muted);font-weight:600;margin-right:6px}.nso-amt-sm{font-family:var(--serif);font-weight:700;font-size:1.8rem;margin:4px 0 8px}.nso-btn{display:flex;align-items:center;justify-content:center;width:100%;min-height:56px;padding:16px 20px;border-radius:999px;background:var(--esp);color:var(--white)!important;text-decoration:none;font:800 .92rem/1.2 var(--sans);letter-spacing:.1em;text-transform:uppercase;box-shadow:0 14px 28px -14px rgba(57,38,31,.7);transition:transform .15s}.nso-btn:hover{transform:translateY(-2px)}.nso-btn.ghost{background:var(--white);color:var(--esp)!important;border:2px solid var(--esp);box-shadow:none;width:auto;display:inline-flex}.nso-btn.is-off{background:#CDBFB9;box-shadow:none;cursor:default}.nso-btn.is-off:hover{transform:none}.nso-faq{background:var(--white);border:1px solid var(--line);border-radius:14px;margin:10px 0;padding:0 16px}.nso-faq summary{cursor:pointer;font-weight:700;padding:15px 0;list-style:none;display:flex;justify-content:space-between;gap:12px}.nso-faq summary::-webkit-details-marker{display:none}.nso-faq summary::after{content:\"+\";font-size:1.3rem;line-height:1;color:var(--rose)}.nso-faq[open] summary::after{content:\"–\"}.nso-faq p{padding:0 0 16px;line-height:1.65;color:var(--muted)}.nso-session{border:1px solid var(--line);border-radius:20px;padding:20px;background:var(--sky-soft)}.nso-session h3{font-family:var(--serif);font-size:1.35rem}@media (min-width:760px){.nso-story{grid-template-columns:320px 1fr}.nso-stats,.nso-parts,.nso-two{grid-template-columns:1fr 1fr}.nso-hero{padding:80px 0 90px}.nso-sec{padding:80px 0}}";
const FONTS = '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&family=Playfair+Display:ital,wght@0,600;0,700;1,600;1,700&display=swap">';
// Pacific time windows (PST is UTC-8 for all of these dates)
const OPEN = Date.UTC(2026, 10, 27, 8, 0, 0);   // Fri Nov 27, 2026 12:00 AM PT: Black Friday opens at $97
const BF_END = Date.UTC(2026, 11, 1, 8, 0, 0);  // Tue Dec 1, 2026 12:00 AM PT: back to $197 on the page
const TITLE = "Never Start Over | The AI Business Starter System | The Nail Bawse™";
const DESC = "Life will pull you out of the chair. Your business shouldn't disappear when it does. AI prompts, a Business Brain dashboard and an AI Front Desk Manager for nail techs and beauty pros.";

function phase(t) { return t < OPEN ? "soon" : (t < BF_END ? "bf" : "full"); }
function asOf(url) {
  const a = url.searchParams.get("asof");
  if (!a || !/^\d{4}-\d{2}-\d{2}$/.test(a)) return null;
  const t = Date.parse(a + "T12:00:00-08:00");
  return isNaN(t) ? null : t;
}
function priceBlock(ph) {
  if (ph === "soon") return '<div class="nso-price"><span class="nso-tag">Black Friday · Opens Fri, Nov 27 · 12 AM PT</span><p class="nso-amt"><s>$197</s>$97</p><span class="nso-btn is-off" aria-disabled="true">Doors open Friday</span><p class="nso-small">4 days only, Nov 27–30. Back to $197 December 1.</p></div>';
  if (ph === "bf") return '<div class="nso-price"><span class="nso-tag">Black Friday · Ends Mon, Nov 30 · 11:59 PM PT</span><p class="nso-amt"><s>$197</s>$97</p><a class="nso-btn" href="/shop/buy">Get Never Start Over · $97</a><p class="nso-small">Instant access on your phone. Back to $197 December 1.</p></div>';
  return '<div class="nso-price"><span class="nso-tag">Instant access</span><p class="nso-amt">$197</p><a class="nso-btn" href="/shop/buy">Get Never Start Over</a><p class="nso-small">Have a promo code? Add it at checkout.</p></div>';
}
function plain(status, text) { return new Response(text, { status: status, headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" } }); }

export async function shop(request, env, ctx) {
  const key = ctx.key, url = new URL(request.url);
  if (request.method !== "GET" && request.method !== "HEAD") return null;

  if (key === "/shop") {
    const ph = phase(asOf(url) ?? Date.now());
    const body = FONTS + "<style>" + CSS + "</style>" + BODY.split("{{PRICE}}").join(priceBlock(ph)).split("{{SESSION_URL}}").join(ctx.SESSION_URL || "/");
    return ctx.html(ctx.page(TITLE, DESC, "/shop", body), 200, env);
  }

  if (key === "/shop/buy") {
    const ph = phase(Date.now());
    const link = ph === "bf" ? env.NSO_LINK_BF : (ph === "full" ? env.NSO_LINK_FULL : "");
    if (!link || !/^https:\/\/(buy|checkout)\.stripe\.com\//.test(String(link))) return Response.redirect("https://" + url.host + "/shop#price", 302);
    return new Response(null, { status: 302, headers: { "location": String(link), "cache-control": "no-store", "referrer-policy": "strict-origin-when-cross-origin" } });
  }

  if (key === "/never-start-over") return Response.redirect("https://" + url.host + "/shop", 302);
  if (key.indexOf("/never-start-over/") === 0) {
    const seg = ctx.path.split("/")[2] || "";
    const tok = env.NSO_TOKEN ? String(env.NSO_TOKEN) : "";
    if (!tok || seg !== tok || !env.NSO_KV) return ctx.respond("/404.html", 404, env);
    const hub = await env.NSO_KV.get("hub.html");
    if (hub === null) return plain(503, "Your access page is updating. Please refresh in a minute.");
    return new Response(hub, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "x-robots-tag": "noindex, nofollow, noarchive",
      "referrer-policy": "no-referrer", "x-content-type-options": "nosniff", "x-frame-options": "DENY" } });
  }
  return null;
}
